  let B,V,root,ghostMesh=null,ghostRing=null,ghostP=null,mini=null,miniBg=null,hillEls=[],timer=0,session=null,room=null,transport=null,lastNet=0,netBusy=false,connectionEpoch=0,pendingEvents=[],architecture=null,worldFx=null,radar=null,territories=null,outposts3D=null,performanceUI=null,towerLevels=null,hud=null,mobileHud=null,mode='coop';
  let profile;try{profile=JSON.parse(localStorage.getItem('owned-front-profile'))||{};}catch{profile={};}
